package com.example.database

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Represents an interactive tool generated by Joya Assistant.
 * Stored locally in Room database so it is never lost.
 */
@Entity(tableName = "created_tools")
data class CreatedToolEntity(
    @PrimaryKey
    val id: String,
    val title: String,
    val prompt: String,
    val category: String,
    val htmlCode: String,
    val createdAt: Long = System.currentTimeMillis(),
    val updatedAt: Long = System.currentTimeMillis()
)
